"""Checks the liquid motion layer: tab line stretch-then-shrink, pointer pull, pull-to-dismiss, seg thumb, focus lines."""
import asyncio, pathlib, sys
from playwright.async_api import async_playwright
URL = "http://127.0.0.1:8771/index.html"
OUT = pathlib.Path(__file__).resolve().parent / "shots"; OUT.mkdir(exist_ok=True)
fails = []
def check(name, ok, extra=""):
    print(("PASS " if ok else "FAIL ") + name + (" " + str(extra) if extra != "" else ""))
    if not ok: fails.append(name)
GL = "(() => { const g=document.querySelector('.tab-glider'); return [parseFloat(g.style.left), parseFloat(g.style.width), g.getBoundingClientRect().height, g.className]; })()"
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(channel="chrome")
        pg = await b.new_page(viewport={"width": 1280, "height": 860})
        errors = []; pg.on("pageerror", lambda e: errors.append(str(e)))
        # the motion checks run on the classic look (the tab line); the glass look has its own checks at the end
        await pg.add_init_script("try { localStorage.setItem('spin-prefs-v1', JSON.stringify({ muted: false, theme: 'system', look: 'classic' })); } catch (e) {}")
        await pg.goto(URL); await pg.wait_for_timeout(1200)
        spring = await pg.evaluate("[getComputedStyle(document.documentElement).getPropertyValue('--spring'), getComputedStyle(document.documentElement).getPropertyValue('--glide'), document.documentElement.hasAttribute('data-spring'), document.getElementById('springSel').checked]")
        check("springy animations are off at first: calm, but the basic pull keeps a real linear() spring", "linear(" not in spring[0] and "linear(" in spring[1] and spring[2:] == [False, False], [spring[0][:24], spring[1][:20], spring[2:]])
        # tab line
        rest = await pg.evaluate(GL)
        tab = await pg.evaluate("(() => { const t=document.querySelector('.tab.is-active'); return [t.offsetLeft, t.offsetWidth]; })()")
        check("line at rest is shorter than its tab", abs(rest[0] - (tab[0] + 10)) < 1 and abs(rest[1] - (tab[1] - 20)) < 1, rest)
        await pg.evaluate("document.querySelector('[data-tab=\"saved\"]').click()")
        mid = await pg.evaluate(GL)
        check("line stretches across both tabs first", mid[1] > rest[1] * 2.5 and "stretch" in mid[3], mid)
        await pg.wait_for_timeout(900)
        end = await pg.evaluate(GL)
        tab2 = await pg.evaluate("(() => { const t=document.querySelector('.tab.is-active'); return [t.offsetLeft, t.offsetWidth]; })()")
        check("then shrinks onto the new tab", abs(end[0] - (tab2[0] + 10)) < 1 and abs(end[1] - (tab2[1] - 20)) < 1 and "settle" in end[3], end)
        await pg.click('[data-tab="options"]'); await pg.wait_for_timeout(900)
        # title line grows on focus
        before = await pg.evaluate("getComputedStyle(document.getElementById('titleInput')).backgroundSize")
        await pg.focus("#titleInput"); await pg.wait_for_timeout(900)
        after = await pg.evaluate("getComputedStyle(document.getElementById('titleInput')).backgroundSize")
        check("title line grows on focus", before.startswith("0%") and after.startswith("100%"), [before, after])
        await pg.evaluate("document.activeElement.blur()"); await pg.wait_for_timeout(900)
        back = await pg.evaluate("getComputedStyle(document.getElementById('titleInput')).backgroundSize")
        check("and shrinks back on blur", back.startswith("0%"), back)
        # pointer pull: nothing leans while springy is off
        box = await pg.locator("#spinBtn").bounding_box()
        await pg.mouse.move(box["x"] + box["width"] - 6, box["y"] + box["height"] / 2); await pg.wait_for_timeout(200)
        calm = await pg.evaluate("[document.getElementById('spinBtn').style.getPropertyValue('--mx'), getComputedStyle(document.getElementById('spinBtn')).transform]")
        check("with springy off, the spin button does not lean", calm[0] in ("", "0px") and calm[1] in ("none", "matrix(1, 0, 0, 1, 0, 0)"), calm)
        await pg.mouse.move(10, 400); await pg.evaluate("document.getElementById('springSel').click()"); await pg.wait_for_timeout(150)
        on = await pg.evaluate("[document.documentElement.hasAttribute('data-spring'), getComputedStyle(document.documentElement).getPropertyValue('--spring').includes('linear('), JSON.parse(localStorage.getItem('spin-prefs-v1')).spring]")
        check("the Settings switch turns springy animations on and remembers it", on == [True, True, True], on)
        await pg.mouse.move(box["x"] + box["width"] - 6, box["y"] + box["height"] / 2); await pg.wait_for_timeout(200)
        mx = await pg.evaluate("parseFloat(document.getElementById('spinBtn').style.getPropertyValue('--mx'))")
        check("spin button is pulled toward the pointer", mx > 4, mx)
        await pg.mouse.move(10, 400); await pg.wait_for_timeout(100)
        mx0 = await pg.evaluate("document.getElementById('spinBtn').style.getPropertyValue('--mx')")
        check("and lets go when the pointer leaves", mx0 == "0px", mx0)
        # winner card: pull a little = springs back, pull far = dismiss
        await pg.click("#spinBtn"); await pg.wait_for_function("window.__spin.spinning === true"); await pg.wait_for_function("window.__spin.spinning === false", timeout=20000); await pg.wait_for_timeout(900)
        cb = await pg.locator(".winner").bounding_box(); cx, cy = cb["x"] + cb["width"] / 2, cb["y"] + 22
        await pg.mouse.move(cx, cy); await pg.mouse.down(); await pg.mouse.move(cx, cy + 50, steps=5)
        pulled = await pg.evaluate("document.querySelector('.winner').style.transform")
        await pg.screenshot(path=str(OUT / "14-pull.png"))
        await pg.mouse.up(); await pg.wait_for_timeout(900)
        check("card follows a pull", "translateY(30" in pulled, pulled)
        check("short pull springs back, card stays", await pg.locator("#overlay").is_visible() and (await pg.evaluate("document.querySelector('.winner').style.transform")) == "")
        await pg.mouse.move(cx, cy); await pg.mouse.down(); await pg.mouse.move(cx, cy + 200, steps=8); await pg.mouse.up(); await pg.wait_for_timeout(500)
        check("long pull dismisses the card", await pg.locator("#overlay").is_hidden())
        # seg thumb
        await pg.click('[data-tab="teams"]'); await pg.wait_for_timeout(700)
        await pg.click("#modeAll"); await pg.wait_for_timeout(900)
        left = await pg.evaluate("(() => { const s=document.querySelector('.seg'); const b=document.getElementById('modeAll'); return [parseFloat(getComputedStyle(s,'::before').left), b.offsetLeft, s.classList.contains('is-all')]; })()")
        check("seg thumb slid under 'All at once'", left[2] and abs(left[0] - left[1]) < 3, left)
        await pg.screenshot(path=str(OUT / "15-seg.png"))
        # appearing: fresh page, things are on their way in, then settled
        pa = await b.new_page(viewport={"width": 1280, "height": 860}); await pa.goto(URL, wait_until="commit")
        await pa.wait_for_function("window.__spin && __spin.shown && __spin.shown().length > 0")
        early = await pa.evaluate("(() => { const sh=__spin.shown(); return [sh[sh.length-1].end, document.body.classList.contains('ready')]; })()")
        check("wheel starts fanned shut and is opening", early[0] < 6.0 and not early[1], early)
        await pa.screenshot(path=str(OUT / "16-appear-early.png"))
        await pa.wait_for_timeout(1700)
        late = await pa.evaluate("(() => { const sh=__spin.shown(); return [sh[sh.length-1].end, document.body.classList.contains('ready'), getComputedStyle(document.getElementById('spinBtn')).opacity]; })()")
        check("wheel fully open and page settled", abs(late[0] - 6.2832) < 0.001 and late[1] and late[2] == "1", late)
        n0 = await pa.locator(".item").count()
        await pa.click("#addBtn"); await pa.wait_for_timeout(40); await pa.keyboard.type("New")
        grow = await pa.evaluate("(() => { const sh=__spin.shown(); const s=sh[sh.length-1]; return s.end - s.start; })()")
        full = 6.2832 / (n0 + 1)
        check("a new slice grows in from a sliver", 0 < grow < full * 0.98, [round(grow, 3), round(full, 3)])
        await pa.screenshot(path=str(OUT / "17-slice-grow.png"))
        await pa.wait_for_timeout(700)
        done = await pa.evaluate("(() => { const sh=__spin.shown(); const s=sh[sh.length-1]; return s.end - s.start; })()")
        check("and reaches its full size", abs(done - full) < 0.001, round(done, 3))
        await pa.click('[data-tab="presets"]'); await pa.wait_for_timeout(60)
        an = await pa.evaluate("getComputedStyle(document.querySelector('.preset')).animationName")
        check("preset cards blob in", an == "blob-in", an)
        await pa.locator(".preset").nth(2).click(); await pa.wait_for_timeout(30)
        ap = await pa.locator(".item.appear").count(); check("loaded options cascade in", ap == 6, ap)
        # a fresh visit gets the classic look; liquid glass is experimental and has to be switched on
        pf = await b.new_page(viewport={"width": 1280, "height": 860}); await pf.goto(URL); await pf.wait_for_timeout(800)
        fresh = await pf.evaluate("[document.documentElement.dataset.look || '', document.getElementById('lookSel').value, document.querySelector('.hub').style.backdropFilter]")
        check("classic is the look on a fresh visit", fresh == ["", "classic", ""], fresh)
        await pf.close()
        pgl = await b.new_page(viewport={"width": 1280, "height": 860}); pgl.on("pageerror", lambda e: errors.append(str(e)))
        await pgl.goto(URL); await pgl.wait_for_timeout(1000)
        await pgl.click('[data-tab="settings"]'); await pgl.wait_for_timeout(600)
        await pgl.select_option("#lookSel", "glass"); await pgl.wait_for_timeout(300)
        await pgl.click('[data-tab="options"]'); await pgl.wait_for_timeout(900)
        g = await pgl.evaluate("""(() => { const t=document.querySelector('.tab.is-active'), gl=document.querySelector('.tab-glider'), tabs=document.querySelector('.tabs');
          const cs = (s) => getComputedStyle(document.querySelector(s));
          return { look: document.documentElement.dataset.look, inline: ['.hub','.bar','.panel','.history','#spinBtn'].map(s => document.querySelector(s).style.backdropFilter).join(''),
                   filters: document.querySelectorAll('filter[id^=lens]').length, panel: cs('.panel').backdropFilter, hub: cs('.hub').backdropFilter, mesh: cs('.mesh').animationName + '/' + cs('.mesh').filter,
                   specs: document.querySelectorAll('.spec i').length,
                   pill: Math.abs(parseFloat(gl.style.left) - t.offsetLeft) < 1 && Math.abs(parseFloat(gl.style.width) - t.offsetWidth) < 1, pillH: gl.getBoundingClientRect().height,
                   fits: tabs.scrollWidth <= tabs.clientWidth + 1, barR: getComputedStyle(document.querySelector('.bar')).borderTopLeftRadius }; })()""")
        check("glass switches on from Settings", g["look"] == "glass", g["look"])
        # the cheap glass: nothing filters the spinning wheel or a pane that only has the still background behind it
        check("no lens or blur filter on the hub or the panes", g["inline"] == "" and g["filters"] == 0 and "blur" not in g["panel"] and "url" not in g["panel"] and g["hub"] == "none", [g["inline"], g["filters"], g["panel"], g["hub"]])
        check("the background is still and not blurred", g["mesh"] == "none/none", g["mesh"])
        px = "(() => { const c=document.querySelector('#spinHub .lens canvas'); if (!c || getComputedStyle(c.parentNode).display === 'none') return 'no lens'; const x=c.getContext('2d'), out=[]; for (let k=0;k<12;k++){ const a=k*Math.PI/6+0.2, d=x.getImageData(Math.round(c.width*(0.5+0.3*Math.cos(a))), Math.round(c.height*(0.5+0.3*Math.sin(a))), 1, 1).data; out.push(d[0]+','+d[1]+','+d[2]+','+d[3]); } return out.join(' '); })()"
        glass_px = await pgl.evaluate(px)
        await pgl.mouse.move(700, 300); await pgl.wait_for_timeout(120)
        sp = await pgl.evaluate("(() => { const p=document.querySelector('.panel'), r=p.getBoundingClientRect(), m=new DOMMatrix(getComputedStyle(p.querySelector('.spec i')).transform); return [Math.round(m.e + r.left), Math.round(m.f + r.top)]; })()")
        check("the highlight slides to the pointer (4 discs, moved by transform)", g["specs"] == 4 and sp == [700, 300], [g["specs"], sp])
        # the one real lens: the winner card, and only once it has stopped moving
        await pgl.click("#spinBtn"); await pgl.wait_for_function("!document.getElementById('overlay').hidden", timeout=20000)
        early = await pgl.evaluate("document.querySelector('.winner').style.backdropFilter")
        await pgl.wait_for_timeout(1100)
        late = await pgl.evaluate("document.querySelector('.winner').style.backdropFilter")
        check("the winner card bends the wheel only after it has settled", early == "" and "#lens-card" in late and late.startswith("url("), [early, late[:30]])
        await pgl.keyboard.press("Escape"); await pgl.wait_for_timeout(500)
        off = await pgl.evaluate("document.querySelector('.winner').style.backdropFilter")
        check("closing the card takes its lens off", off == "", off)
        check("tab thumb is a full glass pill under its tab", g["pill"] and g["pillH"] > 25, [g["pill"], g["pillH"]])
        check("all six tabs fit in the capsule", g["fits"])
        check("bar is a floating capsule", g["barR"] == "999px", g["barR"])
        await pgl.click('[data-tab="settings"]'); await pgl.wait_for_timeout(700)
        await pgl.select_option("#lookSel", "classic"); await pgl.wait_for_timeout(300)
        cl = await pgl.evaluate("[document.documentElement.dataset.look || '', document.querySelector('.hub').style.backdropFilter, JSON.parse(localStorage.getItem('spin-prefs-v1')).look]")
        check("classic switches the glass off and is remembered", cl == ["", "", "classic"], cl)
        classic_px = await pgl.evaluate(px)
        check("the hub paints its own lens in glass only", glass_px != "no lens" and ",255" in glass_px and len(set(glass_px.split())) > 2 and classic_px == "no lens", [glass_px[:44], classic_px[:40]])
        check("no page errors", not errors, errors)
        await b.close()
    print("\n%d failures" % len(fails)); sys.exit(1 if fails else 0)
asyncio.run(main())
